<script setup>
const props=defineProps({groups:{type:Array,required:true},items:{type:Array,required:true},getVariants:{type:Function,required:true},getPrice:{type:Function,required:true},disabled:Boolean})
const emit=defineEmits(['select'])
const active=ref(''),scrollRoot=ref(null)
let frameId=0,jumping=false
function stop(){cancelAnimationFrame(frameId);frameId=0;jumping=false}
onBeforeUnmount(stop)
function jump(name){stop();const root=scrollRoot.value,section=[...root?.querySelectorAll('[data-group]')||[]].find(el=>el.dataset.group===name);if(!root||!section)return;active.value=name;const start=root.scrollTop,target=Math.max(0,Math.min(start+section.getBoundingClientRect().top-root.getBoundingClientRect().top,root.scrollHeight-root.clientHeight));if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){root.scrollTop=target;return}jumping=true;const began=performance.now();function step(now){const t=Math.min(1,(now-began)/160);root.scrollTop=start+(target-start)*(1-(1-t)**3);if(t<1)frameId=requestAnimationFrame(step);else{jumping=false;active.value=name}}frameId=requestAnimationFrame(step)}
function track(){if(jumping)return;const root=scrollRoot.value;if(!root)return;const top=root.getBoundingClientRect().top,section=[...root.querySelectorAll('[data-group]')].filter(el=>el.getBoundingClientRect().top<=top+40).at(-1);if(section)active.value=section.dataset.group}
watch(()=>props.groups,groups=>{if(!groups.some(g=>g[0]===active.value))active.value=groups[0]?.[0]||''},{deep:true,immediate:true})
</script>
<template><div class="menu-column menu-catalog"><div class="categories"><button v-for="g in groups" :key="g[2]||g[0]" type="button" :class="{active:active===g[0]}" @click="jump(g[0])">{{g[0]}}</button></div><div ref="scrollRoot" class="menu-scroll" @wheel.passive="stop" @touchstart.passive="stop" @scroll.passive="track"><section v-for="g in groups" :key="g[2]||g[0]" :data-group="g[0]" class="menu-group"><h2>{{g[0]}}</h2><div class="products"><div v-for="p in items.filter(item=>item.group===g[0])" :key="p.id" class="product"><div class="product-heading"><strong>{{p.name}}</strong><span class="menu-price">{{getPrice(p)}}</span></div><div v-if="getVariants(p).length" class="menu-choices"><button v-for="option in getVariants(p)" :key="option.value" type="button" :class="option.value.startsWith('冰')?'cold':'hot'" :disabled="disabled" @click="emit('select',p,option)">{{option.label}}</button></div><button v-else type="button" class="add-food" :disabled="disabled" @click="emit('select',p)">加入</button></div></div></section></div></div></template>
